'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='summit-math-v1';
let storageOK=true, saved={};
try {saved=JSON.parse(localStorage.getItem(KEY)||'{}');} catch {storageOK=false;}
if(!saved || typeof saved!=='object' || Array.isArray(saved)) saved={};
const state={mode:['AMC 12','AIME'].includes(saved.mode)?saved.mode:'AMC 12',attempts:Array.isArray(saved.attempts)?saved.attempts:[],notes:saved.notes||{},bookmarks:saved.bookmarks||[],scratch:saved.scratch||{},tasks:saved.tasks||{},focus:saved.focus||{},goal:Number(saved.goal)||5,lessons:saved.lessons||[],dailyViews:saved.dailyViews||{},customProblems:Array.isArray(saved.customProblems)?saved.customProblems:[],removedProblems:Array.isArray(saved.removedProblems)?saved.removedProblems:[]};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{storageOK=false;toast('Storage is unavailable. Export your progress before leaving.');return false;}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
const dayKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const dateFromKey=k=>new Date(k+'T12:00:00');
function shiftDay(k,n){const d=dateFromKey(k);d.setDate(d.getDate()+n);return dayKey(d);}
const modeButtons=()=>`<div class="segmented" aria-label="Competition"><button data-mode="AMC 12" class="${state.mode==='AMC 12'?'active':''}" aria-pressed="${state.mode==='AMC 12'}">AMC 12</button><button data-mode="AIME" class="${state.mode==='AIME'?'active':''}" aria-pressed="${state.mode==='AIME'}">AIME</button></div>`;
function heading(title,sub,eyebrow='A LITTLE PROGRESS, EVERY DAY'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${modeButtons()}</div>`;}
function bank(){return allProblems().filter(p=>p.mode===state.mode&&!state.removedProblems.includes(p.id));}
function daily(){const pool=bank();const t=new Date();const days=Math.floor((Date.UTC(t.getFullYear(),t.getMonth(),t.getDate())-Date.UTC(2026,9,20))/86400000);return pool[((days%pool.length)+pool.length)%pool.length];}
function solved(id){return state.attempts.some(a=>a.id===id&&a.correct&&!a.assisted);}
function topicStats(topic){const pool=bank().filter(p=>p.topic===topic);return {total:pool.length,done:pool.filter(p=>solved(p.id)).length};}
function stats(){const attempts=state.attempts.filter(a=>bank().some(p=>p.id===a.id));const eligible=attempts.filter(a=>!a.assisted&&!a.selfReported);const days=new Set(state.attempts.map(a=>a.day));let cursor=dayKey(),streak=0;if(!days.has(cursor))cursor=shiftDay(cursor,-1);while(days.has(cursor)){streak++;cursor=shiftDay(cursor,-1);}const minutes=Math.floor(Object.values(state.focus).reduce((a,b)=>a+b,0)/60);return {solved:bank().filter(p=>solved(p.id)).length,accuracy:eligible.length?Math.round(100*eligible.filter(a=>a.correct).length/eligible.length):null,streak,minutes,attempts};}
function statsCards(){const s=stats();return `<div class="stats"><div class="stat"><div class="stat-top">Problems solved <span class="stat-icon">◈</span></div><div class="stat-value">${s.solved}<small>/ ${bank().length} in ${state.mode}</small></div><div class="stat-foot accent">Includes self-reviewed written work</div></div><div class="stat"><div class="stat-top">Current streak <span class="stat-icon">♧</span></div><div class="stat-value">${s.streak}<small>${s.streak===1?'day':'days'}</small></div><div class="stat-foot">Practice today to keep it going</div></div><div class="stat"><div class="stat-top">Accuracy <span class="stat-icon">◎</span></div><div class="stat-value">${s.accuracy===null?'—':s.accuracy+'%'}<small>unassisted</small></div><div class="stat-foot">Auto-checked, unassisted attempts</div></div><div class="stat"><div class="stat-top">Focus time <span class="stat-icon">◷</span></div><div class="stat-value" id="focus-total">${s.minutes}<small>minutes</small></div><div class="stat-foot">Time in your focus sessions</div></div></div>`;}
let bankPage=1;
let route='today',filters={topic:'All topics',level:'All levels',status:'All problems',format:'All formats',source:'All sources',query:''},pv=null,session=null,focusTimer={remaining:1500,running:false},flashIndex=0,flashBack=false;
const labels={today:'Today',practice:'Problem bank',manage:'Manage problems',learn:'Learn & review',notebook:'My notebook',plan:'Study plan',progress:'My progress',sources:'Sources & license'};
function topicCards(){return `<div class="topic-grid">${TOPICS.map(t=>{const s=topicStats(t.name);return `<a class="topic-card" href="#practice" data-topic-link="${t.name}"><div class="topic-symbol">${t.symbol}</div><h3>${t.name}</h3><p>${s.done} of ${s.total} solved</p><span class="arrow">↗</span><div class="progress-line"><span style="width:${s.total?100*s.done/s.total:0}%"></span></div></a>`;}).join('')}</div>`;}
function todayPage(){const p=daily();const cached=state.dailyViews[dayKey()+state.mode];pv=p?(cached&&bank().some(q=>q.id===cached.id)?cached:newView(p.id,'daily')):null;return `${heading('A new day. A new problem.','Small steps today. Stronger problem solving tomorrow.')}<section class="hero"><div><div class="eyebrow">THE WAY UP IS THROUGH</div><h2>Big ideas start with<br><em>one good problem.</em></h2><p>Your daily dose of curiosity, persistence, and a little pencil work.</p></div><svg class="hero-art" viewBox="0 0 300 200" aria-hidden="true"><circle cx="140" cy="100" r="87"/><path d="M55 165 140 24l88 141H55ZM55 165 184 94M140 24l0 141M96 95h87M140 24 228 165"/><circle cx="140" cy="119" r="46"/><path d="M20 165h245M140 9v180"/></svg><a href="#practice" class="btn">Find your next challenge <span>↗</span></a></section>${statsCards()}<div class="today-grid"><section><div class="section-heading"><h2>Problem of the day</h2><span class="badge orange">✦ A FRESH CHALLENGE</span></div><div id="daily-problem">${pv?problemHTML(pv):emptyBankHTML()}</div></section><aside class="today-right"><div class="section-heading"><h2>Your next steps</h2><a href="#plan" class="subtle-link">View plan ↗</a></div><div class="roadmap"><a href="#today" class="roadmap-item"><span class="step-number">01</span><div class="step-copy"><h3>Warm up your thinking</h3><p>Try today’s problem · 10–15 min</p></div><span class="arrow">↗</span></a><a href="#learn" class="roadmap-item"><span class="step-number">02</span><div class="step-copy"><h3>Build a stronger foundation</h3><p>A short lesson + a worked example</p></div><span class="arrow">↗</span></a><a href="#notebook" class="roadmap-item"><span class="step-number">03</span><div class="step-copy"><h3>Turn mistakes into progress</h3><p>Revisit your error notebook</p></div><span class="arrow">↗</span></a></div>${weekHTML()}</aside></div><section class="explore"><div class="section-heading"><h2>A little practice in every direction</h2><a href="#learn" class="subtle-link">Explore topics ↗</a></div>${topicCards()}</section>`;}
function weekStart(){const d=new Date();const n=(d.getDay()+6)%7;d.setDate(d.getDate()-n);return dayKey(d);}
function weekHTML(){let count=0;const days=Array.from({length:7},(_,i)=>{const key=shiftDay(weekStart(),i);const done=state.attempts.some(a=>a.day===key);if(done)count++;return `<div class="week-day"><span>${['M','T','W','T','F','S','S'][i]}</span><span class="day-circle ${done?'done':''} ${key===dayKey()?'current':''}" title="${key}${done?': practiced':''}">${done?'✓':dateFromKey(key).getDate()}</span></div>`;});return `<div class="week-card"><div class="week-title">Show up for yourself<span>${count} / ${state.goal} days</span></div><div class="week-days">${days.join('')}</div><p>${count?'Every session counts. Keep your rhythm.':'Your first session is the start of something.'}</p></div>`;}
function newView(id,context){return {id,context,selected:'',hints:0,revealed:false,submitted:false,correct:false,assisted:false};}
const triangle=`<svg class="diagram" viewBox="0 0 330 145" role="img" aria-label="Triangle with sides 13, 14, 15 and an incircle of radius r. Diagram not to scale."><path class="fill" d="M55 125 145 8 285 125Z"/><circle cx="156" cy="87" r="38"/><path d="M156 87v38M156 116h9v9" stroke-dasharray="3 3"/><text x="89" y="63">13</text><text x="224" y="63">15</text><text x="155" y="142">14</text><text x="166" y="107">r</text><circle cx="156" cy="87" r="2"/></svg>`;
function problemHTML(v){
 const p=allProblems().find(p=>p.id===v.id),locked=v.submitted,written=p.format==='written';
 return `<article class="problem-card"><div class="problem-top"><div class="problem-meta"><span class="badge">${esc(p.mode)}</span><span class="badge orange">${esc(p.topic)}</span><span class="meta-text">${esc(p.level)} · ${p.source?'CEMC archive':p.custom?'Added by you':'Original practice'}</span></div><button class="bookmark ${state.bookmarks.includes(p.id)?'saved':''}" data-action="bookmark" aria-label="${state.bookmarks.includes(p.id)?'Unsave':'Save'} problem">${state.bookmarks.includes(p.id)?'◆':'◇'}</button></div>
 <div class="problem-body"><h3>${esc(p.title)}</h3><p class="problem-text">${esc(p.text)}</p>${p.diagram?triangle:''}${p.source?sourceQuestionHTML(p):''}
 ${written?'<div class="written-notice"><b>Written response · self-reviewed</b><p>Write your solution in the scratchpad or on paper. Compare with the official worked solution, then record how you did.</p></div>':p.choices?`<div class="answers" role="group" aria-label="Answer choices">${p.choices.map((c,i)=>`<button class="answer ${v.selected===c?'selected':''}" data-choice="${esc(c)}" aria-pressed="${v.selected===c}" ${locked?'disabled':''}><span>${p.format==='mc-letter'?'CHOOSE':'ABCDE'[i]}</span>${esc(c)}</button>`).join('')}</div>`:`<label class="meta-text" for="integer-answer" style="display:block;margin-top:16px">Your integer answer (000–999)</label><input id="integer-answer" class="field answer-input" inputmode="numeric" pattern="[0-9]{1,3}" maxlength="3" placeholder="000" value="${esc(v.selected)}" ${locked?'disabled':''} autocomplete="off">`}
 <div class="problem-actions">${written?'':`<button class="btn" data-action="submit-answer" ${locked?'disabled':''}>${locked?'Answer submitted':'Check answer'} →</button>`}<div class="quiet-wrap">${p.hints.length?`<button class="quiet" data-action="hint" ${v.hints>=p.hints.length?'disabled':''}>☼ ${v.hints?'Another hint':'Need a hint?'}</button>`:''}<button class="${written?'btn':'quiet'}" data-action="solution" ${v.revealed?'disabled':''}>${p.source?'View official solution':'View solution'} ↗</button></div></div>
 ${v.submitted?`<div class="feedback ${v.correct?'correct':''}" role="status">${v.selfReported?(v.correct?'Recorded as solved before checking · self-assessed.':'Marked for more practice. This problem is in your notebook.'):v.correct?(v.assisted?'Correct with support. Revisit it later for an independent solve.':'Nicely done. You found it.'):`Not quite. The correct answer is ${esc(p.answer)}. This problem is in your notebook.`}</div>`:''}
 ${p.hints.slice(0,v.hints).map((h,i)=>`<div class="hint-box"><b>Hint ${i+1}.</b> ${esc(h)}</div>`).join('')}
 <div class="scratch"><label for="scratch-text">YOUR SCRATCHPAD · notes save as you type</label><textarea id="scratch-text" placeholder="What do you notice? Try an idea here…">${esc(state.scratch[p.id]||'')}</textarea></div>
 ${v.revealed?`<div class="solution"><h4>${p.source?'Official worked solution':'A way through'}</h4>${p.source?sourceSolutionHTML(p):p.steps.map((s,i)=>`<p><b>${i+1}.</b> ${esc(s)}</p>`).join('')}${p.idea?`<div class="key-idea"><b>Takeaway:</b> ${esc(p.idea)}</div>`:''}</div>`:''}
 ${written&&v.revealed&&!locked?'<div class="self-review"><p>How did your work compare? This is your own assessment, not an automatic grade.</p><div><button class="btn" data-self-review="solved">Solved before checking ✓</button><button class="btn secondary" data-self-review="revisit">Needs more practice</button></div></div>':''}
 ${session&&v.context==='session'?`<div class="problem-actions"><span class="meta-text">Question ${session.index+1} of ${session.ids.length}</span><button class="btn secondary" data-action="next-session">${session.index===session.ids.length-1?'Finish set':'Next problem'} →</button></div>`:''}</div>
 <div class="problem-bottom"><span>${p.source?'Follow the original contest’s instructions.':'Make space to think. No calculator needed.'}</span><span>${v.context==='daily'?'Changes daily · Your local date':'Learn something worth keeping.'}</span></div></article>`;
}
function updateProblem(){if(pv?.context==='daily'){state.dailyViews[dayKey()+state.mode]={...pv};save();}const target=pv?.context==='daily'?$('#daily-problem'):$('#modal-problem');if(target)target.innerHTML=problemHTML(pv);}
function practicePage(){return `${heading('Find your next challenge.','Explore original and sourced problems, one idea at a time.','THE PROBLEM BANK')}<div class="bank-tools"><span class="meta-text">Make this bank your own.</span><div><a class="quiet" href="#manage">Manage problems ↗</a><button class="btn secondary" data-action="add-problem">＋ Add problem</button></div></div><div class="session-banner"><div><h3>A little pressure. A lot of practice.</h3><p>Build a set of up to 5 problems using your filters. Written work uses self-review.</p></div><div class="session-controls"><label class="meta-text" for="session-duration">Set timer</label><select class="field" id="session-duration"><option value="15">15 minutes</option><option value="30">30 minutes</option><option value="45">45 minutes</option></select><button class="btn" data-action="start-session">Start a timed set ↗</button></div></div><div class="filters"><input class="field" id="search-problems" aria-label="Search problems" placeholder="Search for an idea or problem…" value="${esc(filters.query)}"><select class="field" id="topic-filter" aria-label="Filter by topic">${['All topics',...TOPICS.map(t=>t.name)].map(t=>`<option ${filters.topic===t?'selected':''}>${t}</option>`).join('')}</select><select class="field" id="level-filter" aria-label="Filter by difficulty">${['All levels','Foundation','Core','Stretch'].map(t=>`<option ${filters.level===t?'selected':''}>${t}</option>`).join('')}</select><select class="field" id="status-filter" aria-label="Filter by status">${['All problems','Unsolved','Solved','Saved'].map(t=>`<option ${filters.status===t?'selected':''}>${t}</option>`).join('')}</select><select class="field" id="source-filter" aria-label="Filter by source">${['All sources','Starter bank','Added by me','Fermat','Euclid','CSMC'].map(t=>`<option ${filters.source===t?'selected':''}>${t}</option>`).join('')}</select><select class="field" id="format-filter" aria-label="Filter by answer format">${['All formats','Auto checked','Written response'].map(t=>`<option ${filters.format===t?'selected':''}>${t}</option>`).join('')}</select></div><div id="problem-results">${problemResults()}</div><p class="meta-text" style="margin-top:20px">${allProblems().filter(p=>!state.removedProblems.includes(p.id)).length} practice problems across both tracks, including your additions. Foundation → Core → Stretch are study labels, not official contest positions. Topic and difficulty tags are approximate study labels. Written responses use self-review and do not affect auto-checked accuracy. Timed sets are short practice drills. <a href="#sources" class="subtle-link">Sources &amp; license ↗</a></p>`;}
function filtered(){return bank().filter(p=>(filters.topic==='All topics'||p.topic===filters.topic)&&(filters.level==='All levels'||p.level===filters.level)&&(filters.status==='All problems'||filters.status==='Unsolved'&&!solved(p.id)||filters.status==='Solved'&&solved(p.id)||filters.status==='Saved'&&state.bookmarks.includes(p.id))&&(filters.format==='All formats'||(filters.format==='Written response')===(p.format==='written'))&&(filters.source==='All sources'||filters.source==='Starter bank'&&!p.source&&!p.custom||filters.source==='Added by me'&&p.custom||p.source===filters.source)&&`${p.title} ${p.text} ${p.topic} ${p.idea} ${p.searchText||''}`.toLowerCase().includes(filters.query.toLowerCase()));}
function problemResults(){const pool=filtered();const pages=Math.max(1,Math.ceil(pool.length/25));bankPage=Math.min(bankPage,pages);const shown=pool.slice((bankPage-1)*25,bankPage*25);return `<div class="section-heading"><span class="meta-text">${pool.length} problems · ${state.mode}</span><button class="quiet" data-action="reset-filters">Reset filters</button></div><div class="problem-list">${pool.length?shown.map(p=>`<button class="problem-row" data-open="${p.id}"><span class="number">${String(bank().indexOf(p)+1).padStart(2,'0')}</span><span><h3>${esc(p.title)}</h3><p>${esc(p.topic)} · ${esc(p.level)}${p.source?' · '+p.source:''}${p.format==='written'?' · Written':''}</p></span><span class="badge">${esc(p.mode)}</span><span class="difficulty">${esc(p.level)}</span><span class="result-icon">${solved(p.id)?'✓ Solved':state.bookmarks.includes(p.id)?'◆ Saved':'Practice ↗'}</span></button>`).join(''):`<div class="empty"><h2>No problems here yet.</h2><p>Try another topic, level, or status.</p><button class="btn secondary" data-action="reset-filters">Clear filters</button></div>`}</div>${paginationHTML(bankPage,pages,'bank',pool.length)}`;}
function learnPage(){return `${heading('Collect ideas. Make connections.','A few useful tools, with room to understand why they work.','LEARN & REVIEW')}<div class="study-grid">${TOPICS.map((t,i)=>`<button class="lesson-card" data-lesson="${i}"><span class="badge">${String(i+1).padStart(2,'0')} · ${state.lessons.includes(t.name)?'REVISIT':'CONCEPT GUIDE'}</span><h2>${t.name}</h2><p>${t.intro}</p><span class="subtle-link">4 short sections · Worked example <span style="float:right">Read lesson ↗</span></span></button>`).join('')}</div><section class="flashcard-panel"><div class="section-heading"><h2>Keep the essentials close</h2><span class="badge">RECALL CARDS</span></div><p class="meta-text">Try to recall the answer before you turn the card.</p><div id="flashcard-wrap">${flashHTML()}</div></section>`;}
function flashHTML(){const f=FLASHCARDS[flashIndex];return `<button class="flashcard" data-action="flip-card" aria-label="${flashBack?'Show question':'Reveal answer'}"><small>${flashBack?'THE IDEA':'QUICK RECALL'}</small><strong>${f[flashBack?1:0]}</strong><small>Click to ${flashBack?'see the question':'reveal the answer'}</small></button><div class="flash-controls"><button class="quiet" data-action="prev-card">← Previous</button><span>${flashIndex+1} / ${FLASHCARDS.length}</span><button class="quiet" data-action="next-card">Next →</button></div>`;}
function showLesson(i){const t=TOPICS[i];$('#lesson-modal').innerHTML=`<div class="modal-bar"><span class="eyebrow">THE TOOLKIT / ${t.name}</span><button class="close" data-action="close-lesson" aria-label="Close lesson">×</button></div><article class="lesson-content"><h2 id="lesson-title">${t.intro}</h2><div class="formula">${t.formula}</div>${t.sections.map(([h,p])=>`<h3>${h}</h3><p>${p}</p>`).join('')}<div class="hint-box"><b>A common trap:</b> ${t.trap}</div><div class="problem-actions"><button class="btn" data-complete-lesson="${i}">${state.lessons.includes(t.name)?'Reviewed ✓':'Mark as read ✓'}</button><button class="quiet" data-lesson-practice="${t.name}">Practice ${t.name.toLowerCase()} ↗</button></div></article>`;$('#lesson-dialog').showModal();}
function notebookPage(){const ids=Object.keys(state.notes).filter(id=>bank().some(p=>p.id===id));return `${heading('Your mistakes are good teachers.','Save the idea you missed. Come back and solve it independently.','MY NOTEBOOK')}<div class="section-heading"><h2>${ids.length} ${ids.length===1?'problem':'problems'} to learn from</h2><span class="meta-text">Missed answers are added automatically</span></div>${ids.length?ids.map(id=>{const p=allProblems().find(p=>p.id===id),n=state.notes[id];return `<article class="notebook-card"><div class="notebook-head"><div><span class="badge orange">${esc(p.topic)}</span> <span class="meta-text">${n.reviewed?'✓ Reviewed':'Ready to revisit'}</span><h3 style="margin-top:8px">${esc(p.title)}</h3></div><button class="btn secondary" data-open="${id}">Try again ↗</button></div><div class="notebook-fields"><label>What got in the way?<select class="field" data-note-reason="${id}">${['Not sure yet','Missing concept','Wrong approach','Calculation error','Misread the problem','Time pressure'].map(r=>`<option ${n.reason===r?'selected':''}>${r}</option>`).join('')}</select></label><label>The idea I want to remember<textarea class="field" data-note-text="${id}" placeholder="Write the key step in your own words…">${esc(n.text)}</textarea></label></div><div class="note-actions"><button class="quiet" data-review="${id}">${n.reviewed?'Mark for review':'Mark reviewed ✓'}</button><button class="quiet" data-remove-note="${id}">Remove from notebook</button></div></article>`;}).join(''):`<div class="empty"><div class="empty-icon">✎</div><h2>Leave a trail of good ideas.</h2><p>Miss a problem and it will appear here. You can also save any problem from its solution to review later.</p><a class="btn" href="#practice">Find a problem →</a></div>`}`;}
function planPage(){const tasks=[['Monday','Build a foundation','Read one concept guide, then solve 2 problems.','35 min','learn'],['Tuesday','Practice with intention','Solve 3 problems on one topic. Write the key idea.','30 min','practice'],['Wednesday','Close the loop','Re-solve 2 missed problems without reading the solutions.','25 min','notebook'],['Thursday','Mix things up','Try 3 problems from different topics.','35 min','practice'],['Friday','Keep the tools sharp','Recall 8 flashcards, then try the daily problem.','20 min','learn'],['Saturday','Find your rhythm','Complete a timed set and review every skipped or missed problem.','45 min','practice'],['Sunday','Pause and reflect','Review your notebook and pick a focus for next week.','20 min','notebook']];return `${heading('A plan you can keep.','A suggested weekly rhythm. Adjust the pace to fit your week.','STUDY PLAN')}<div class="plan-layout"><div>${tasks.map((t,i)=>{const k=weekStart()+'-'+i;return `<section class="plan-day"><h3>${t[0]} <span class="meta-text" style="float:right">${t[3]}</span></h3><label class="task-check ${state.tasks[k]?'completed':''}"><input type="checkbox" data-task="${k}" ${state.tasks[k]?'checked':''}><span>${t[1]}<small>${t[2]}</small></span></label><a class="subtle-link" href="#${t[4]}">Open workspace ↗</a></section>`;}).join('')}</div><aside><div class="info-card"><span class="eyebrow">CONSISTENCY OVER INTENSITY</span><h2>Show up. Think deeply.<br>Come back tomorrow.</h2><p>This starter plan is about 3½ hours a week. Use extra sessions for a full diagnostic and careful error analysis as your goals grow.</p><label class="meta-text" for="weekly-goal">MY WEEKLY PRACTICE GOAL</label><select class="field" id="weekly-goal" style="display:block;width:100%;margin:8px 0 22px">${[3,4,5,6,7].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} days a week</option>`).join('')}</select><div class="section-heading"><h3>One focused block</h3><span class="timer-chip"><span id="focus-clock">${clockText(focusTimer.remaining)}</span><button data-action="focus-toggle">${focusTimer.running?'Pause':'Start'}</button><button data-action="focus-reset" aria-label="Reset focus timer">↺</button></span></div><p>A 25-minute timer for uninterrupted work. Focus time counts while this page is open.</p><ul><li>Attempt before opening a hint.</li><li>Explain the key step in your own words.</li><li>Revisit mistakes after a day or two.</li></ul></div>${weekHTML()}</aside></div>`;}
function progressPage(){const s=stats();return `${heading('See how far you’ve come.','A record of your work, with a little perspective.','MY PROGRESS')}${statsCards()}<section class="progress-topics"><div class="section-heading"><h2>Your topic map</h2><span class="meta-text">Independent solves / available problems</span></div>${TOPICS.map(t=>{const x=topicStats(t.name);return `<div class="progress-topic"><span>${t.name}</span><div class="progress-line"><span style="width:${x.total?100*x.done/x.total:0}%"></span></div><small>${x.done} / ${x.total}</small></div>`;}).join('')}<p class="meta-text">Solves using a hint or an open solution count as supported practice. Re-solve independently to add them here.</p></section><section class="explore"><div class="section-heading"><h2>Recent attempts</h2><button class="quiet" data-action="export">Export progress ↗</button></div>${s.attempts.length?s.attempts.slice(-12).reverse().map(a=>{const p=allProblems().find(p=>p.id===a.id);return `<div class="history-row"><span>${esc(p.title)}<small> · ${esc(p.topic)}</small></span><span>${a.selfReported?(a.correct?'Self-reviewed · solved':'Self-reviewed · revisit'):a.correct?(a.assisted?'With support':'✓ Correct'):'Revisit'} <small>· ${a.day}</small></span></div>`;}).join(''):`<div class="empty"><h2>Your story starts with a problem.</h2><p>Submit an answer to begin tracking your work.</p><a class="btn" href="#today">Try today’s problem →</a></div>`}</section>`;}
function render(){const incoming=location.hash.slice(1);route=labels[incoming]?incoming:'today';$('#crumb').textContent=labels[route];document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===route);if(a.dataset.nav===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#date-label').textContent=new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'});const pages={today:todayPage,practice:practicePage,manage:managerPage,learn:learnPage,notebook:notebookPage,plan:planPage,progress:progressPage,sources:sourcesPage};$('#main').innerHTML=(!storageOK?'<div class="storage-warning">Browser storage is unavailable. Use Export my progress to keep a copy before leaving.</div>':'')+pages[route]();updateCount();}
function updateCount(){$('#note-count').textContent=Object.keys(state.notes).length;}
function openProblem(id,context='practice'){if(!allProblems().some(p=>p.id===id))return;pv=newView(id,context);$('#problem-modal').innerHTML=`<div class="modal-bar"><h2 id="problem-title">${context==='session'?'TIMED PRACTICE':'A LITTLE TIME TO THINK'}</h2>${context==='session'?`<span class="timer-chip" id="session-clock">${clockText(session.remaining)}</span>`:''}<button class="close" data-action="close-problem" aria-label="Close problem">×</button></div><div class="modal-inner" id="modal-problem">${problemHTML(pv)}</div>`;if(!$('#problem-dialog').open)$('#problem-dialog').showModal();}
function closeProblem(){if(session){finishSession('Set ended early. Unanswered problems are listed as skipped.');return;}$('#problem-dialog').close();render();}
function clockText(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function submit(){if(!pv||pv.submitted)return;const p=allProblems().find(p=>p.id===pv.id);if(p.format==='written')return;if(!p.choices){const input=$('#integer-answer');if(!input||!/^\d{1,3}$/.test(input.value)){toast('Enter an integer from 000 to 999.');input?.focus();return;}pv.selected=String(Number(input.value));}if(!pv.selected){toast('Choose an answer first.');return;}pv.correct=pv.selected===p.answer;pv.submitted=true;pv.assisted=pv.hints>0||pv.revealed;state.attempts.push({id:p.id,correct:pv.correct,assisted:pv.assisted,day:dayKey(),time:Date.now()});if(!pv.correct)addNote(p.id);if(session&&pv.context==='session')session.results[p.id]={correct:pv.correct,assisted:pv.assisted};save();updateCount();updateProblem();if(pv.context==='daily')refreshStats();}
function addNote(id){if(!state.notes[id])state.notes[id]={reason:'Not sure yet',text:'',reviewed:false};else state.notes[id].reviewed=false;}
function refreshStats(){const el=$('.stats');if(el){const t=document.createElement('div');t.innerHTML=statsCards();el.replaceWith(t.firstElementChild);}if(route==='today'){const week=$('.week-card');if(week)week.outerHTML=weekHTML();const topics=$('.topic-grid');if(topics)topics.outerHTML=topicCards();}}
function startSession(){const pool=filtered();if(!pool.length){toast('No problems match these filters. Clear a filter first.');return;}const ids=[...pool].sort(()=>Math.random()-.5).slice(0,5).map(p=>p.id);session={ids,index:0,remaining:Number($('#session-duration').value)*60,results:{},started:Date.now()};openProblem(ids[0],'session');}
function finishSession(message='A little more experienced than before.'){if(!session)return;const s=session;session=null;const correct=Object.values(s.results).filter(r=>r.correct&&!r.assisted).length;$('#problem-modal').innerHTML=`<div class="modal-bar"><h2 id="problem-title">SET COMPLETE</h2><button class="close" data-action="close-summary" aria-label="Close summary">×</button></div><div class="session-summary"><span class="eyebrow">GOOD WORK SHOWING UP</span><h2>Every attempt teaches something.</h2><div class="big-score">${correct}<span style="font-size:22px;color:#a1b18d"> / ${s.ids.length}</span></div><p>${message}<br>${correct} independent ${correct===1?'solve':'solves'} · ${Object.values(s.results).filter(r=>r.correct&&r.assisted).length} supported · ${s.ids.filter(id=>!s.results[id]).length} skipped</p>${s.ids.map(id=>{const p=allProblems().find(p=>p.id===id),r=s.results[id];return `<div class="history-row"><span>${esc(p.title)}</span><span>${r?(r.selfReported?(r.correct?'Self-reviewed · solved':'Self-reviewed · revisit'):r.correct?(r.assisted?'With support':'✓ Correct'):'Review in notebook'):'Skipped'}</span></div>`;}).join('')}<div class="problem-actions"><button class="btn secondary" data-action="close-summary">Back to practice</button><button class="btn" data-action="summary-notebook">Open notebook →</button></div></div>`;save();}
function exportData(){const blob=new Blob([JSON.stringify({app:'Summit',version:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=`summit-progress-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);toast('Progress exported as JSON.');}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;const d=el.dataset;if(d.mode){bankPage=1;managerPageNumber=1;state.mode=d.mode;save();render();return;}if(d.topicLink){filters.topic=d.topicLink;if(route==='practice')render();}if(d.open){openProblem(d.open);return;}if(d.choice&&pv&&!pv.submitted){pv.selected=d.choice;updateProblem();return;}if(d.lesson!==undefined){showLesson(Number(d.lesson));return;}if(d.completeLesson!==undefined){const t=TOPICS[Number(d.completeLesson)].name;if(!state.lessons.includes(t))state.lessons.push(t);save();el.textContent='Read ✓';toast('Lesson marked as read.');return;}if(d.lessonPractice){filters.topic=d.lessonPractice;$('#lesson-dialog').close();location.hash='practice';if(route==='practice')render();return;}if(d.review){state.notes[d.review].reviewed=!state.notes[d.review].reviewed;save();render();return;}if(d.removeNote){delete state.notes[d.removeNote];save();render();toast('Removed from notebook.');return;}switch(d.action){case 'submit-answer':submit();break;case 'bookmark':if(pv){const i=state.bookmarks.indexOf(pv.id);if(i<0)state.bookmarks.push(pv.id);else state.bookmarks.splice(i,1);save();updateProblem();toast(i<0?'Problem saved. Find it in the bank’s Saved filter.':'Problem unsaved.');}break;case 'hint':if(pv){pv.hints++;updateProblem();}break;case 'solution':if(pv){pv.revealed=true;addNote(pv.id);save();updateCount();updateProblem();}break;case 'close-problem':closeProblem();break;case 'close-summary':$('#problem-dialog').close();render();break;case 'summary-notebook':$('#problem-dialog').close();location.hash='notebook';if(route==='notebook')render();break;case 'close-lesson':$('#lesson-dialog').close();render();break;case 'start-session':startSession();break;case 'next-session':if(session){if(session.index===session.ids.length-1)finishSession();else{session.index++;openProblem(session.ids[session.index],'session');}}break;case 'reset-filters':bankPage=1;filters={topic:'All topics',level:'All levels',status:'All problems',format:'All formats',source:'All sources',query:''};render();break;case 'flip-card':flashBack=!flashBack;$('#flashcard-wrap').innerHTML=flashHTML();break;case 'prev-card':case 'next-card':flashIndex=(flashIndex+(d.action==='next-card'?1:-1)+FLASHCARDS.length)%FLASHCARDS.length;flashBack=false;$('#flashcard-wrap').innerHTML=flashHTML();break;case 'focus-toggle':focusTimer.running=!focusTimer.running;el.textContent=focusTimer.running?'Pause':'Start';break;case 'focus-reset':focusTimer={remaining:1500,running:false};$('#focus-clock').textContent=clockText(1500);$('[data-action="focus-toggle"]').textContent='Start';break;case 'export':exportData();break;}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='search-problems'){bankPage=1;filters.query=el.value;$('#problem-results').innerHTML=problemResults();}if(el.id==='integer-answer'&&pv)pv.selected=el.value;if(el.id==='scratch-text'&&pv){state.scratch[pv.id]=el.value;save();}if(el.dataset.noteText){state.notes[el.dataset.noteText].text=el.value;save();}});
document.addEventListener('change',e=>{const el=e.target;const mapping={'topic-filter':'topic','level-filter':'level','status-filter':'status','source-filter':'source','format-filter':'format'};if(mapping[el.id]){bankPage=1;filters[mapping[el.id]]=el.value;$('#problem-results').innerHTML=problemResults();}if(el.dataset.noteReason){state.notes[el.dataset.noteReason].reason=el.value;save();}if(el.dataset.task){state.tasks[el.dataset.task]=el.checked;save();el.closest('.task-check').classList.toggle('completed',el.checked);}if(el.id==='weekly-goal'){state.goal=Number(el.value);save();render();}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='integer-answer'){e.preventDefault();submit();}});
$('#problem-dialog').addEventListener('cancel',e=>{e.preventDefault();closeProblem();});
$('#lesson-dialog').addEventListener('close',()=>{if(route==='learn')render();});
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){$('#main').focus();return;}render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('pagehide',save);
let lastTick=Date.now(),lastDay=dayKey();
setInterval(()=>{const now=Date.now();const elapsed=Math.floor((now-lastTick)/1000);if(elapsed<1)return;lastTick+=elapsed*1000;if(focusTimer.running){const used=Math.min(elapsed,focusTimer.remaining);focusTimer.remaining-=used;state.focus[dayKey()]=(state.focus[dayKey()]||0)+used;if($('#focus-clock'))$('#focus-clock').textContent=clockText(focusTimer.remaining);if(focusTimer.remaining<=0){focusTimer.running=false;if($('[data-action="focus-toggle"]'))$('[data-action="focus-toggle"]').textContent='Start';toast('Focus block complete. Take a short break.');}save();}if(session){session.remaining=Math.max(0,session.remaining-elapsed);if($('#session-clock'))$('#session-clock').textContent=clockText(session.remaining);if(session.remaining===0)finishSession('Time is up. Review what you tried, then revisit the rest.');}if(lastDay!==dayKey()){lastDay=dayKey();if(!$('#problem-dialog').open)render();}},1000);
render();
